class Solution {
    int find(vector<int>& p, int x){ while(p[x]!=x){ p[x]=p[p[x]]; x=p[x]; } return x; }
    void unite(vector<int>& p, int a, int b){ a=find(p,a); b=find(p,b); if(a!=b) p[a]=b; }
public:
    string findTheString(vector<vector<int>>& lcp) {
        int n = lcp.size();
        for(int i=0;i<n;i++){
            if(lcp[i][i] != n-i) return "";
            for(int j=0;j<i;j++) if(lcp[i][j] != lcp[j][i]) return "";
        }
        vector<int> p(n);
        for(int i=0;i<n;i++) p[i]=i;
        for(int i=0;i<n;i++)
            for(int j=i+1;j<n;j++)
                if(lcp[i][j] > 0) unite(p, i, j);
        vector<int> col(n, -1);
        vector<vector<int>> occ(26);
        for(int i=0;i<n;i++){
            if(col[i] == -1){
                for(int c=0;c<26;c++){
                    bool ok = true;
                    for(int j : occ[c])
                        if(lcp[j][i] == 0){ ok=false; break; }
                    if(ok){ col[i]=c; occ[c].push_back(i); break; }
                }
                if(col[i] == -1) return "";
            } else {
                occ[col[i]].push_back(i);
            }
        }
        string w(n, 'a');
        for(int i=0;i<n;i++) w[i] = 'a' + col[i];
        vector<int> cur(n+1, 0), nxt(n+1, 0);
        for(int i=n-1;i>=0;i--){
            for(int j=n-1;j>=0;j--){
                int v;
                if(w[i] != w[j]) v = 0;
                else v = (i+1 < n && j+1 < n) ? nxt[j+1] + 1 : 1;
                if(v != lcp[i][j]) return "";
                cur[j] = v;
            }
            swap(cur, nxt);
        }
        return w;
    }
};
